package id.velioragardens.veliorasuite.module.kits;
import id.velioragardens.veliorasuite.util.ColorUtil; import org.bukkit.Bukkit; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class KitAdminCommand implements CommandExecutor, TabCompleter { private final KitManager manager; public KitAdminCommand(KitManager manager){this.manager=manager;} @Override public boolean onCommand(CommandSender sender, Command command, String label, String[] args){ if(!sender.hasPermission("veliorasuite.kits.admin")){sender.sendMessage(ColorUtil.color("&cKamu tidak punya izin.")); return true;} if(args.length==0){help(sender); return true;} switch(args[0].toLowerCase(Locale.ROOT)){ case "reload" -> {manager.reload(); sender.sendMessage(ColorUtil.color("&aVelioraKits berhasil direload."));} case "give" -> { if(args.length<3){sender.sendMessage(ColorUtil.color("&cGunakan: /vkits give <player> <kit>")); return true;} Player t=Bukkit.getPlayerExact(args[1]); if(t==null){sender.sendMessage(ColorUtil.color("&cPlayer tidak online.")); return true;} manager.claim(t,args[2],true); sender.sendMessage(ColorUtil.color("&aKit diberikan."));} case "reset" -> { if(args.length<3){sender.sendMessage(ColorUtil.color("&cGunakan: /vkits reset <player> <kit>")); return true;} Player t=Bukkit.getPlayerExact(args[1]); if(t==null){sender.sendMessage(ColorUtil.color("&cPlayer tidak online.")); return true;} manager.reset(t,args[2]); sender.sendMessage(ColorUtil.color("&aCooldown kit direset."));} case "list" -> sender.sendMessage(ColorUtil.color("&aKits: &f"+String.join(", ", manager.kitIds()))); default -> help(sender);} return true;} private void help(CommandSender s){s.sendMessage(ColorUtil.color("&e/vkit reload &7- Reload kits")); s.sendMessage(ColorUtil.color("&e/vkits give <player> <kit> &7- Beri kit")); s.sendMessage(ColorUtil.color("&e/vkits reset <player> <kit> &7- Reset cooldown"));} @Override public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args){ if(args.length==1)return filter(Arrays.asList("reload","give","reset","list"),args[0]); if(args.length==3 && (args[0].equalsIgnoreCase("give")||args[0].equalsIgnoreCase("reset"))) return filter(manager.kitIds(),args[2]); return new ArrayList<>();} private List<String> filter(List<String> o,String i){List<String>r=new ArrayList<>();String l=i.toLowerCase(Locale.ROOT);for(String x:o)if(x.toLowerCase(Locale.ROOT).startsWith(l))r.add(x);return r;} }
